// Diesel schema for the widgets domain of the unified-db-platform bounded context.
//
// Split out of `src/schema.rs` (see `src/lib.rs`); the table below
// is byte-identical to migration 2026-11-23-000129_widget_layouts.
// The file is named `widgets.rs` (not `widget_layouts.rs`) so the
// `pub mod widgets` binding never collides with the table module
// `widget_layouts` generated by the `diesel::table!` block (see the
// name-collision rule in `src/schema.rs`).

diesel::table! {
    widget_layouts (id) {
        id -> Uuid,
        context -> Varchar,
        scope_kind -> Varchar,
        scope_id -> Varchar,
        owner_id -> Varchar,
        items -> Jsonb,
        created_at -> Timestamptz,
        updated_at -> Timestamptz,
    }
}
